//! Generates machined's gRPC API (`proto/machined/v1/machined.proto`) as cladefs's build does its
//! own: compiled by protox (no protoc), generated by madsim's tonic-build, as tonic has it. And
//! hotbed's API (`hotbed/proto/hotbed/v1/hotbed.proto`, hotbed's own, copied: hotbed/README.md),
//! its messages alone, for machined's hotbed node (src/hotbed), with its descriptors, which say
//! what WorkspaceService's calls are.

use std::path::Path;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let out = std::path::PathBuf::from(std::env::var("OUT_DIR")?);

    let protos = ["proto/machined/v1/machined.proto"];
    let set = descriptors(&["proto"], &protos, &out.join("machined.bin"))?;
    madsim_tonic_build::configure()
        .file_descriptor_set_path(&set)
        .skip_protoc_run()
        .compile_protos(&protos, &["proto"])?;

    let hotbed = ["hotbed/proto/hotbed/v1/hotbed.proto"];
    let set = descriptors(&["hotbed/proto"], &hotbed, &out.join("hotbed.bin"))?;
    madsim_tonic_build::configure()
        .build_client(false)
        .build_server(false)
        .file_descriptor_set_path(&set)
        .skip_protoc_run()
        .compile_protos(&hotbed, &["hotbed/proto"])?;
    Ok(())
}

/// Compiles `protos` (under `includes`) with protox, and writes their descriptors to `set`.
fn descriptors(
    includes: &[&str],
    protos: &[&str],
    set: &Path,
) -> Result<std::path::PathBuf, Box<dyn std::error::Error>> {
    for proto in protos {
        println!("cargo:rerun-if-changed={proto}");
    }
    let mut compiler = protox::Compiler::new(includes)?;
    compiler.include_imports(true).include_source_info(true).open_files(protos)?;
    std::fs::write(set, compiler.encode_file_descriptor_set())?;
    Ok(set.to_owned())
}
